/**
 * Server-side generated values for `@code` and `@generated` fields.
 *
 * Generated by Qiy; do not edit. Codes are rendered on the server from the
 * configured timezone (QIY_CODE_TIMEZONE, default UTC) and a database-backed
 * sequence, never accepted from a client. See docs/dsl/generated-values.md.
 */
import { and, eq, sql } from "drizzle-orm";
import { db } from "./db";
import { qiyCodeSequences } from "./schema";

export interface QiyGeneratedField {
  field: string;
  kind: "code" | "uuid";
  template?: string;
}

export const QIY_GENERATED_ATTEMPTS = 5;

/** A bounded retry could not allocate a unique generated value; REST answers 409. */
export class QiyGeneratedValueConflict extends Error {
  constructor(entity: string) {
    super("Could not allocate a unique generated value for " + entity + " after " + QIY_GENERATED_ATTEMPTS + " attempts");
    this.name = "QiyGeneratedValueConflict";
  }
}

/** A pattern reached the runtime that the Qiy generator should have rejected. */
export class QiyCodeTemplateError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "QiyCodeTemplateError";
  }
}

export type QiyCodeDatePart = "YYYY" | "YY" | "MM" | "DD" | "HH" | "mm" | "ss" | "SSS";
export const qiyCodeDatePartNames: QiyCodeDatePart[] = ["YYYY", "YY", "MM", "DD", "HH", "mm", "ss", "SSS"];

export type QiyCodeTemplateToken =
  | { kind: "literal"; value: string }
  | { kind: "uuid" }
  | { kind: "date"; part: QiyCodeDatePart }
  | { kind: "sequence"; width: number }
  | { kind: "random"; length: number; charset: string };

const QIY_DEFAULT_RANDOM_CHARSET = "a-zA-Z0-9";

function qiyExpandCharset(charset: string): string {
  if (!charset) throw new QiyCodeTemplateError("A generated-code random charset must not be empty");
  const characters: string[] = [];
  for (let index = 0; index < charset.length; index++) {
    const current = charset[index]!;
    if (charset[index + 1] === "-") {
      const end = charset[index + 2];
      if (!end || !/[0-9A-Za-z]/.test(current) || !/[0-9A-Za-z]/.test(end) || end.charCodeAt(0) <= current.charCodeAt(0)) {
        throw new QiyCodeTemplateError("Invalid generated-code random charset range " + JSON.stringify(charset));
      }
      for (let code = current.charCodeAt(0); code <= end.charCodeAt(0); code++) {
        const character = String.fromCharCode(code);
        if (!characters.includes(character)) characters.push(character);
      }
      index += 2;
      continue;
    }
    if (!/[0-9A-Za-z]/.test(current)) throw new QiyCodeTemplateError("Generated-code random charset characters must be ASCII alphanumerics: " + JSON.stringify(charset));
    if (!characters.includes(current)) characters.push(current);
  }
  if (!characters.length) throw new QiyCodeTemplateError("A generated-code random charset must contain at least one character");
  return characters.join("");
}

function qiyRandomWidth(width: number, maximum: number): number {
  if (!Number.isInteger(width) || width < 1 || width > maximum) throw new QiyCodeTemplateError("Generated-code width must be between 1 and " + maximum);
  return width;
}

/** Splits a concatenated date token such as {YYYYMMDD} or {HHmmss} into its parts. */
function qiyDatePartSequence(body: string): QiyCodeDatePart[] | undefined {
  const parts: QiyCodeDatePart[] = [];
  let index = 0;
  while (index < body.length) {
    const rest = body.slice(index);
    if (rest.startsWith("YYYY")) { parts.push("YYYY"); index += 4; continue; }
    if (rest.startsWith("SSS")) { parts.push("SSS"); index += 3; continue; }
    const two = rest.slice(0, 2);
    if (two === "YY" || two === "MM" || two === "DD" || two === "HH" || two === "mm" || two === "ss") { parts.push(two); index += 2; continue; }
    return undefined;
  }
  return parts.length ? parts : undefined;
}

/** Parses one generated-code pattern; mirrors tools/code-template.ts. */
export function qiyParseCodeTemplate(pattern: string): QiyCodeTemplateToken[] {
  if (typeof pattern !== "string" || pattern.length === 0) throw new QiyCodeTemplateError("A generated-code pattern must be a non-empty string");
  const tokens: QiyCodeTemplateToken[] = [];
  const pushLiteral = (value: string) => {
    if (!value) return;
    const previous = tokens[tokens.length - 1];
    if (previous?.kind === "literal") previous.value += value;
    else tokens.push({ kind: "literal", value });
  };
  let index = 0;
  let literal = "";
  while (index < pattern.length) {
    const character = pattern[index]!;
    if (character === "{") {
      if (pattern[index + 1] === "{") { literal += "{"; index += 2; continue; }
      const end = pattern.indexOf("}", index + 1);
      if (end === -1) throw new QiyCodeTemplateError("Unclosed token in generated-code pattern " + JSON.stringify(pattern));
      const body = pattern.slice(index + 1, end).trim();
      const dateParts = qiyDatePartSequence(body);
      if (dateParts) {
        pushLiteral(literal);
        literal = "";
        for (const part of dateParts) tokens.push({ kind: "date", part });
        index = end + 1;
        continue;
      }
      let token: QiyCodeTemplateToken;
      if (body === "uuid") token = { kind: "uuid" };
      else if (qiyCodeDatePartNames.includes(body as QiyCodeDatePart)) token = { kind: "date", part: body as QiyCodeDatePart };
      else {
        const sequence = /^(\$\.)?(seq|count\+1)(?::(\d+))?$/.exec(body);
        if (sequence) {
          token = { kind: "sequence", width: sequence[3] ? qiyRandomWidth(Number(sequence[3]), 12) : 1 };
        } else {
          const random = /^random:(\d+)(?::(.*))?$/.exec(body);
          const natural = random ? undefined : /^random(?:\s+([^\s]+))?\s+length\s+(\d+)$/.exec(body);
          if (random) token = { kind: "random", length: qiyRandomWidth(Number(random[1]), 256), charset: qiyExpandCharset(random[2] ?? QIY_DEFAULT_RANDOM_CHARSET) };
          else if (natural) token = { kind: "random", length: qiyRandomWidth(Number(natural[2]), 256), charset: qiyExpandCharset((natural[1] ?? QIY_DEFAULT_RANDOM_CHARSET).replaceAll("/", "")) };
          else throw new QiyCodeTemplateError("Unsupported token {" + body + "} in generated-code pattern " + JSON.stringify(pattern));
        }
      }
      pushLiteral(literal);
      literal = "";
      tokens.push(token);
      index = end + 1;
      continue;
    }
    if (character === "}") {
      if (pattern[index + 1] === "}") { literal += "}"; index += 2; continue; }
      throw new QiyCodeTemplateError("Unescaped } in generated-code pattern " + JSON.stringify(pattern));
    }
    literal += character;
    index += 1;
  }
  pushLiteral(literal);
  return tokens;
}

/** The IANA timezone used by date/time tokens; QIY_CODE_TIMEZONE, default UTC. */
export function qiyCodeTimeZone(): string {
  const configured = Bun.env.QIY_CODE_TIMEZONE?.trim();
  return configured && configured.length > 0 ? configured : "UTC";
}

const qiyDateFormatters = new Map<string, Intl.DateTimeFormat>();

/** Renders the date/time parts of one instant in the configured timezone. */
export function qiyCodeDateParts(now: Date, timeZone: string): Record<QiyCodeDatePart, string> {
  let formatter = qiyDateFormatters.get(timeZone);
  if (!formatter) {
    try {
      formatter = new Intl.DateTimeFormat("en-GB", { timeZone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" });
    } catch {
      throw new Error("QIY_CODE_TIMEZONE is not a valid IANA timezone: " + JSON.stringify(timeZone));
    }
    qiyDateFormatters.set(timeZone, formatter);
  }
  const values: Record<string, string> = {};
  for (const part of formatter.formatToParts(now)) if (part.type !== "literal") values[part.type] = part.value;
  const year = values.year ?? "0000";
  return {
    YYYY: year,
    YY: year.slice(-2),
    MM: values.month ?? "00",
    DD: values.day ?? "00",
    HH: values.hour ?? "00",
    mm: values.minute ?? "00",
    ss: values.second ?? "00",
    SSS: String(now.getMilliseconds()).padStart(3, "0"),
  };
}

function qiyRandomString(length: number, charset: string): string {
  // Rejection sampling keeps the distribution uniform instead of biasing the
  // low characters through a modulo.
  const maximum = 256 - (256 % charset.length);
  let result = "";
  while (result.length < length) {
    const bytes = crypto.getRandomValues(new Uint8Array(length));
    for (const byte of bytes) {
      if (byte >= maximum) continue;
      result += charset[byte % charset.length]!;
      if (result.length === length) break;
    }
  }
  return result;
}

export interface QiyCodeRenderOptions {
  now?: Date;
  timeZone?: string;
  sequence?: number;
  uuid?: string;
  random?: (length: number, charset: string) => string;
}

/** Renders a generated-code pattern. Sequence tokens share one allocated number. */
export function qiyRenderCodeTemplate(pattern: string, options: QiyCodeRenderOptions = {}): string {
  const tokens = qiyParseCodeTemplate(pattern);
  const now = options.now ?? new Date();
  const timeZone = options.timeZone ?? qiyCodeTimeZone();
  const parts = tokens.some((token) => token.kind === "date") ? qiyCodeDateParts(now, timeZone) : undefined;
  const sequence = options.sequence ?? 0;
  const uuid = options.uuid ?? crypto.randomUUID();
  const random = options.random ?? qiyRandomString;
  let rendered = "";
  for (const token of tokens) {
    if (token.kind === "literal") rendered += token.value;
    else if (token.kind === "uuid") rendered += uuid;
    else if (token.kind === "date") rendered += parts ? parts[token.part] : "";
    else if (token.kind === "sequence") rendered += String(sequence).padStart(token.width, "0");
    else rendered += random(token.length, token.charset);
  }
  return rendered;
}

/** The sequence bucket: every date/time token rendered in order, or "" without one. */
export function qiyCodeTemplateBucket(pattern: string, now: Date = new Date(), timeZone: string = qiyCodeTimeZone()): string {
  const tokens = qiyParseCodeTemplate(pattern);
  const dateParts = tokens.flatMap((token) => token.kind === "date" ? [token.part] : []);
  if (!dateParts.length) return "";
  const rendered = qiyCodeDateParts(now, timeZone);
  return dateParts.map((part) => rendered[part]).join("");
}

/**
 * Allocates the next sequence value for one entity/field/bucket. The single
 * upsert statement is atomic, so concurrent creates cannot read the same value.
 */
async function qiyNextSequence(entity: string, field: string, bucket: string): Promise<number> {
  const row = db.insert(qiyCodeSequences)
    .values({ entity, field, bucket, value: 1 })
    .onConflictDoUpdate({ target: [qiyCodeSequences.entity, qiyCodeSequences.field, qiyCodeSequences.bucket], set: { value: sql`${qiyCodeSequences.value} + 1` } })
    .returning({ value: qiyCodeSequences.value })
    .get();
  return Number(row?.value ?? 1);
}


/** A unique-constraint violation from any supported dialect. */
export function qiyIsUniqueViolation(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const code = String((error as { code?: unknown }).code ?? "");
  if (["23505", "ER_DUP_ENTRY", "SQLITE_CONSTRAINT", "SQLITE_CONSTRAINT_UNIQUE", "2067"].includes(code)) return true;
  const message = error instanceof Error ? error.message : typeof error === "string" ? error : "";
  return /UNIQUE constraint failed|duplicate key value violates unique constraint|Duplicate entry .+ for key/i.test(message);
}

/** Renders every generated value of one entity: codes from the sequence table, UUIDs fresh. */
export async function qiyGenerateValues(entity: string, fields: readonly QiyGeneratedField[], options: { now?: Date; timeZone?: string } = {}): Promise<Record<string, unknown>> {
  const now = options.now ?? new Date();
  const timeZone = options.timeZone ?? qiyCodeTimeZone();
  const values: Record<string, unknown> = {};
  for (const field of fields) {
    if (field.kind === "uuid") { values[field.field] = crypto.randomUUID(); continue; }
    if (!field.template) throw new QiyCodeTemplateError("Generated code field " + field.field + " has no template");
    const sequence = await qiyNextSequence(entity, field.field, qiyCodeTemplateBucket(field.template, now, timeZone));
    values[field.field] = qiyRenderCodeTemplate(field.template, { now, timeZone, sequence });
  }
  return values;
}

/** Removes client-supplied generated fields without mutating the input. */
export function qiyStripGeneratedValues<T extends Record<string, unknown>>(values: T, fields: readonly QiyGeneratedField[]): T {
  let result: Record<string, unknown> | undefined;
  for (const field of fields) {
    if (!Object.hasOwn(values, field.field)) continue;
    result ??= { ...values };
    delete result[field.field];
  }
  return (result ?? values) as T;
}

/**
 * Runs one create with freshly generated values. Client-supplied values for
 * generated fields are ignored; a unique-constraint conflict retries with new
 * values a bounded number of times and then surfaces QiyGeneratedValueConflict.
 */
export async function qiyCreateWithGeneratedValues<T>(entity: string, fields: readonly QiyGeneratedField[], values: Record<string, unknown>, run: (prepared: Record<string, unknown>) => Promise<T> | T): Promise<T> {
  const base = qiyStripGeneratedValues(values, fields);
  for (let attempt = 0; attempt < QIY_GENERATED_ATTEMPTS; attempt++) {
    const generated = await qiyGenerateValues(entity, fields);
    try {
      return await run({ ...base, ...generated });
    } catch (error) {
      if (!qiyIsUniqueViolation(error)) throw error;
    }
  }
  throw new QiyGeneratedValueConflict(entity);
}
